    if n == 1:
        return 0
    best = float('inf')
    for mask in range(1, 1 << n):
        if bin(mask).count('1') != n - 1:
            continue
        prev = -1
        cost = dist[0][mask & 1]
        for i in range(1, n - 1):
            if mask & (1 << i):
                prev = i
        for i in range(n - 1):
            if not (mask & (1 << i)):
                continue
            if prev >= 0 and dist[prev][i] < 0:
                continue
            if i == n - 2:
                cost += dist[i][0]
            else:
                nxt = i + 1
                while not (mask & (1 << nxt)):
                    nxt += 1
                cost += dist[i][nxt]
                prev = nxt
        best = min(best, cost)
    return best
